alter table public.products enable row level security;
alter table public.cart_items enable row level security;

-- Explicit privilege hardening (RLS still governs row visibility)
revoke insert, update, delete, truncate, references, trigger on public.products from anon, authenticated;
revoke all on public.cart_items from anon;
grant select on public.products to anon, authenticated;
grant select, insert, update, delete on public.cart_items to authenticated;

-- Helper: is the referenced product active? (security definer so the check is
-- independent of the caller's row visibility on public.products)
create function public.product_is_active(pid bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce((select p.is_active from public.products p where p.id = pid), false);
$$;

revoke execute on function public.product_is_active(bigint) from public, anon;
grant execute on function public.product_is_active(bigint) to authenticated;

-- R1: anyone can read active products; inactive rows are only reachable via service_role (bypasses RLS)
create policy products_select_active
  on public.products
  for select
  to anon, authenticated
  using (is_active = true);

-- R2: no insert/update/delete policies for anon/authenticated -> writes are denied.
-- (service_role bypasses RLS and retains full access, R6)

-- R3 / R5: signed-in users can read only their own cart items; anon has no policy -> denied
create policy cart_items_select_own
  on public.cart_items
  for select
  to authenticated
  using (user_id = auth.uid());

-- R4 (add): own cart only, and only for active products
create policy cart_items_insert_own
  on public.cart_items
  for insert
  to authenticated
  with check (
    user_id = auth.uid()
    and public.product_is_active(product_id)
  );

-- R4 (change quantity): own cart only, and only for active products
create policy cart_items_update_own
  on public.cart_items
  for update
  to authenticated
  using (
    user_id = auth.uid()
    and public.product_is_active(product_id)
  )
  with check (
    user_id = auth.uid()
    and public.product_is_active(product_id)
  );

-- R4 (remove): own cart only, and only for active products
create policy cart_items_delete_own
  on public.cart_items
  for delete
  to authenticated
  using (
    user_id = auth.uid()
    and public.product_is_active(product_id)
  );
