create or replace function public.send_points(p_to uuid, p_amount integer)
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_from uuid := auth.uid();
  v_id bigint;
begin
  if v_from is null then
    raise exception 'send_points: not authenticated' using errcode = '28000';
  end if;

  if p_amount is null or p_amount <= 0 then
    raise exception 'send_points: amount must be positive' using errcode = '22023';
  end if;

  if p_to is null then
    raise exception 'send_points: recipient is required' using errcode = '22023';
  end if;

  if p_to = v_from then
    raise exception 'send_points: cannot send points to yourself' using errcode = '22023';
  end if;

  perform 1
    from public.wallets
   where user_id in (v_from, p_to)
   order by user_id
   for update;

  if not exists (select 1 from public.wallets where user_id = v_from) then
    raise exception 'send_points: sender wallet not found' using errcode = 'P0002';
  end if;

  if not exists (select 1 from public.wallets where user_id = p_to) then
    raise exception 'send_points: recipient wallet not found' using errcode = 'P0002';
  end if;

  update public.wallets
     set balance = balance - p_amount
   where user_id = v_from
     and balance >= p_amount;

  if not found then
    raise exception 'send_points: insufficient funds' using errcode = 'P0001';
  end if;

  update public.wallets
     set balance = balance + p_amount
   where user_id = p_to;

  insert into public.transfers (from_user, to_user, amount)
  values (v_from, p_to, p_amount)
  returning id into v_id;

  return v_id;
end;
$$;

revoke all on function public.send_points(uuid, integer) from public, anon;
grant execute on function public.send_points(uuid, integer) to authenticated;
