  if auth.role() = 'service_role' then
    return new;
  end if;

  if old.returned_on is not null then
    raise exception 'returned loans cannot be modified';
  end if;

  if new.id <> old.id
     or new.book_id <> old.book_id
     or new.borrower_id <> old.borrower_id
     or new.borrowed_on <> old.borrowed_on then
    raise exception 'only returned_on may be changed on a loan';
  end if;

  if new.returned_on is null then
    raise exception 'returned_on must be set when returning a loan';
  end if;

  return new;
end;
$$;

