-- not archived, and the resulting row must still be on a board where the
-- user is an editor and which is not archived.
create policy cards_update_editor
  on public.cards
  for update
  to authenticated
  using (
    public.is_board_editor(board_id)
    and not public.is_board_archived(board_id)
  )
  with check (
    public.is_board_editor(board_id)
    and not public.is_board_archived(board_id)
  );

-- R3 + R4 + R5: only editors can delete cards, only on non-archived boards.
create policy cards_delete_editor
  on public.cards
  for delete
  to authenticated
  using (
    public.is_board_editor(board_id)
    and not public.is_board_archived(board_id)
  );

-- R6: no insert/update/delete policies exist on boards or board_members,
-- so all writes there are denied for anon and authenticated.
-- R7: anon has no policies and no table privileges.
-- R8: service_role bypasses RLS and retains full access.
