create or replace function public.leave_requests_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.employee_id is distinct from auth.uid() then
      raise exception 'employee_id must be the current user';
    end if;
    if new.status <> 'pending' then
      raise exception 'new leave requests must be pending';
    end if;
    if new.decided_by is not null then
      raise exception 'new leave requests cannot have a decider';
    end if;
    return new;
  end if;

  if old.status <> 'pending' then
    raise exception 'only pending leave requests can be modified';
  end if;

  if new.id is distinct from old.id then
    raise exception 'id cannot be changed';
  end if;

  if new.employee_id is distinct from old.employee_id then
    raise exception 'employee_id cannot be changed';
  end if;

  if new.employee_id = auth.uid() then
    if new.status not in ('pending', 'cancelled') then
      raise exception 'employees cannot approve or reject their own requests';
    end if;
    if new.decided_by is not null then
      raise exception 'employees cannot set decided_by';
    end if;
  else
    if not public.is_manager_of(auth.uid(), old.employee_id) then
      raise exception 'only the direct manager can decide this request';
    end if;
    if new.status not in ('approved', 'rejected') then
      raise exception 'managers must approve or reject';
    end if;
    if new.decided_by is distinct from auth.uid() then
      raise exception 'decided_by must be the deciding manager';
    end if;
    if new.starts_on is distinct from old.starts_on
       or new.ends_on is distinct from old.ends_on
       or new.note is distinct from old.note then
      raise exception 'managers cannot change request details';
    end if;
  end if;

  return new;
end;
$$;

create trigger leave_requests_guard
before insert or update on public.leave_requests
for each row execute function public.leave_requests_guard();

