create function public.leave_requests_guard()
returns trigger
language plpgsql
set search_path = public
as $$
declare
  is_service boolean;
begin
  is_service := current_user = 'service_role'
    or coalesce(auth.role(), current_setting('request.jwt.claim.role', true), '') = 'service_role';

  if tg_op = 'DELETE' then
    if is_service then
      return old;
    end if;
    raise exception 'leave requests cannot be deleted';
  end if;

  if tg_op = 'UPDATE' then
    if is_service then
      return new;
    end if;

    if old.status <> 'pending' then
      raise exception 'only pending leave requests can be changed';
    end if;

    if new.employee_id <> old.employee_id then
      raise exception 'employee_id cannot be changed';
    end if;

    if old.employee_id = auth.uid() then
      if new.status not in ('pending', 'cancelled') then
        raise exception 'employees cannot approve or reject their own requests';
      end if;
      if new.decided_by is not null then
        raise exception 'decided_by must remain null for employee changes';
      end if;
      return new;
    end if;

    if exists (
      select 1
      from public.employees e
      where e.user_id = old.employee_id
        and e.manager_id = auth.uid()
        and old.employee_id <> auth.uid()
    ) then
      if new.status not in ('approved', 'rejected') then
        raise exception 'managers must approve or reject';
      end if;
      if new.decided_by is distinct from auth.uid() then
        raise exception 'decided_by must be the deciding manager';
      end if;
      if new.starts_on <> old.starts_on
         or new.ends_on <> old.ends_on
         or new.note is distinct from old.note then
        raise exception 'deciding cannot change dates or note';
      end if;
      return new;
    end if;

    raise exception 'not allowed to change this leave request';
  end if;

  return new;
end;
$$;

