  actor uuid := auth.uid();
  actor_is_own boolean;
  actor_is_manager boolean;
begin
  if current_user in ('postgres', 'service_role', 'supabase_admin')
     or coalesce(auth.role(), '') = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.employee_id is distinct from actor then
      raise exception 'leave requests may only be created for oneself';
    end if;
    if new.status <> 'pending' or new.decided_by is not null then
      raise exception 'new leave requests must be pending and undecided';
    end if;
    return new;
  end if;

