  if old.status <> 'pending' then
    raise exception 'leave request is no longer pending';
  end if;

  if new.employee_id is distinct from old.employee_id then
    raise exception 'employee_id may not be changed';
  end if;

  actor_is_own := old.employee_id = actor;
  actor_is_manager := exists (
    select 1
    from public.employees e
    where e.user_id = old.employee_id
      and e.manager_id = actor
  );

  if actor_is_own then
    if new.status not in ('pending', 'cancelled') then
      raise exception 'employees may only keep or cancel their own pending requests';
    end if;
    if new.decided_by is not null then
      raise exception 'employees cannot record a decision';
    end if;
    return new;
  end if;

  if actor_is_manager then
    if new.starts_on is distinct from old.starts_on
       or new.ends_on is distinct from old.ends_on
       or new.note is distinct from old.note then
      raise exception 'deciding a request cannot change its dates or note';
    end if;
    if new.status not in ('approved', 'rejected') then
      raise exception 'a manager must approve or reject the request';
    end if;
    if new.decided_by is distinct from actor then
      raise exception 'decided_by must be the deciding manager';
    end if;
    return new;
  end if;

  raise exception 'not allowed to update this leave request';
end;
$$;

