create function public.leave_requests_guard()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  actor uuid := auth.uid();
  actor_role text := auth.role();
begin
  if tg_op = 'DELETE' then
    if actor_role = 'service_role' then
      return old;
    end if;
    raise exception 'leave requests cannot be deleted';
  end if;

  if actor_role = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.employee_id is distinct from actor then
      raise exception 'employees can only create their own leave requests';
    end if;
    if new.status <> 'pending' or new.decided_by is not null then
      raise exception 'new leave requests must be pending and undecided';
    end if;
    return new;
  end if;

  if old.status <> 'pending' then
    raise exception 'only pending leave requests can be changed';
  end if;

  if new.employee_id is distinct from old.employee_id then
    raise exception 'employee_id cannot be changed';
  end if;

  if new.status = old.status then
    if new.status <> 'pending' then
      raise exception 'invalid status transition';
    end if;
    if actor is distinct from old.employee_id then
      raise exception 'only the employee can edit a pending request';
    end if;
    if new.decided_by is not null then
      raise exception 'decided_by must be null while pending';
    end if;
    return new;
  end if;

  if new.status = 'cancelled' then
    if actor is distinct from old.employee_id then
      raise exception 'only the employee can cancel their request';
    end if;
    if new.decided_by is not null then
      raise exception 'decided_by must be null when cancelled';
    end if;
    if new.starts_on is distinct from old.starts_on
       or new.ends_on is distinct from old.ends_on
       or new.note is distinct from old.note then
      raise exception 'cancelling cannot change dates or note';
    end if;
    return new;
  end if;

  if new.status in ('approved', 'rejected') then
    if actor is null or actor = old.employee_id then
      raise exception 'employees cannot decide their own requests';
    end if;
    if not public.is_direct_manager_of(actor, old.employee_id) then
      raise exception 'only the direct manager can decide this request';
    end if;
    if new.decided_by is distinct from actor then
      raise exception 'decided_by must be the deciding manager';
    end if;
    if new.starts_on is distinct from old.starts_on
       or new.ends_on is distinct from old.ends_on
       or new.note is distinct from old.note then
      raise exception 'deciding cannot change dates or note';
    end if;
    return new;
  end if;

  raise exception 'invalid status transition';
end;
$$;

