```sql
alter table public.friendships enable row level security;
alter table public.posts enable row level security;

-- Helper: are two users friends (accepted friendship in either direction)?
-- SECURITY DEFINER so it can read friendships without triggering RLS recursion.
create or replace function public.are_friends(a uuid, b uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.friendships f
    where f.status = 'accepted'
      and (
        (f.requester_id = a and f.addressee_id = b)
        or (f.requester_id = b and f.addressee_id = a)
      )
  );
$$;

revoke all on function public.are_friends(uuid, uuid) from public;
revoke all on function public.are_friends(uuid, uuid) from anon;
grant execute on function public.are_friends(uuid, uuid) to authenticated;
grant execute on function public.are_friends(uuid, uuid) to service_role;

-- Guard: friendships can only move pending -> accepted, and participants are immutable.
create or replace function public.enforce_friendship_update()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.requester_id <> old.requester_id or new.addressee_id <> old.addressee_id then
    raise exception 'friendship participants cannot be changed';
  end if;
  if not (old.status = 'pending' and new.status = 'accepted') then
    raise exception 'only a pending request can be accepted';
  end if;
  return new;
end;
$$;

drop trigger if exists friendships_enforce_update on public.friendships;
create trigger friendships_enforce_update
  before update on public.friendships
  for each row
  execute function public.enforce_friendship_update();

-- friendships: read only rows you are part of
create policy friendships_select_involved
  on public.friendships
  for select
  to authenticated
  using (requester_id = auth.uid() or addressee_id = auth.uid());

-- friendships: send requests as yourself, always pending
create policy friendships_insert_request
  on public.friendships
  for insert
  to authenticated
  with check (
    requester_id = auth.uid()
    and addressee_id <> auth.uid()
    and status = 'pending'
  );

-- friendships: only the addressee may accept a pending request
create policy friendships_update_accept
  on public.friendships
  for update
  to authenticated
  using (addressee_id = auth.uid() and status = 'pending')
  with check (addressee_id = auth.uid() and status = 'accepted');

-- friendships: either participant may delete (unfriend / cancel / decline)
create policy friendships_delete_involved
  on public.friendships
  for delete
  to authenticated
  using (requester_id = auth.uid() or addressee_id = auth.uid());

-- posts: anonymous visitors see public posts only
create policy posts_select_anon
  on public.posts
  for select
  to anon
  using (audience = 'public');

-- posts: signed-in users see public, own, and friends-only posts from friends
create policy posts_select_authenticated
  on public.posts
  for select
  to authenticated
  using (
    audience = 'public'
    or author_id = auth.uid()
    or (audience = 'friends' and public.are_friends(auth.uid(), author_id))
  );

-- posts: create only as yourself
create policy posts_insert_own
  on public.posts
  for insert
  to authenticated
  with check (author_id = auth.uid());

-- posts: edit only your own, and never reassign authorship
create policy posts_update_own
  on public.posts
  for update
  to authenticated
  using (author_id = auth.uid())
  with check (author_id = auth.uid());

-- posts: delete only your own
create policy posts_delete_own
  on public.posts
  for delete
  to authenticated
  using (author_id = auth.uid());

-- Privileges
revoke all on public.friendships from anon;
grant select, insert, update, delete on public.friendships to authenticated;
grant all on public.friendships to service_role;

revoke all on public.posts from anon;
grant select on public.posts to anon;
grant select, insert, update, delete on public.posts to authenticated;
grant all on public.posts to service_role;

grant usage, select on sequence public.posts_id_seq to authenticated;
grant usage, select on sequence public.posts_id_seq to service_role;
