    if new.product_id is distinct from old.product_id
       or new.user_id is distinct from old.user_id then
      raise exception 'review product_id and user_id cannot be changed';
    end if;

    if new.is_featured is distinct from old.is_featured then
      raise exception 'is_featured can only be changed by staff';
    end if;

    return new;
  end if;

  return new;
end;
$$;

