-- ---------------------------------------------------------------------------
-- listings: SELECT
-- ---------------------------------------------------------------------------

-- R1: public marketplace view
create policy listings_select_public
on public.listings
for select
to anon, authenticated
using (
  status = 'active'
  and is_flagged = false
  and deleted_at is null
);

-- R2: sellers see all of their own listings (drafts, flagged, deleted)
create policy listings_select_own
on public.listings
for select
to authenticated
using (seller_id = auth.uid());

-- R2: moderators see every listing
create policy listings_select_moderator
on public.listings
for select
to authenticated
using (public.is_moderator(auth.uid()));

-- ---------------------------------------------------------------------------
-- listings: INSERT  (R3)
-- ---------------------------------------------------------------------------
create policy listings_insert_own
on public.listings
for insert
to authenticated
with check (
  seller_id = auth.uid()
  and is_flagged = false
  and deleted_at is null
);

-- ---------------------------------------------------------------------------
-- listings: UPDATE
-- ---------------------------------------------------------------------------

-- R3/R4: sellers edit their own non-deleted listings; removal is an UPDATE
-- that sets deleted_at. Once deleted_at is set the USING clause no longer
-- matches, so the listing becomes immutable for its seller.
create policy listings_update_own
on public.listings
for update
to authenticated
using (
  seller_id = auth.uid()
  and deleted_at is null
)
with check (
  seller_id = auth.uid()
);

-- R5: moderators can change any listing (flag/unflag, etc.)
create policy listings_update_moderator
on public.listings
for update
to authenticated
using (public.is_moderator(auth.uid()))
with check (public.is_moderator(auth.uid()));

-- No DELETE policies anywhere -> R6 (no hard deletes) is enforced by RLS.

-- ---------------------------------------------------------------------------
-- Trigger: column-level immutability that WITH CHECK cannot express
-- (sellers must not flag/unflag, must not re-assign seller_id, and must not
-- touch a listing that is already soft-deleted).
-- ---------------------------------------------------------------------------
create or replace function public.listings_before_update()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if not public.is_moderator(auth.uid()) then
    if new.seller_id is distinct from old.seller_id then
      raise exception 'seller_id cannot be changed';
    end if;
    if new.is_flagged is distinct from old.is_flagged then
      raise exception 'is_flagged can only be changed by a moderator';
    end if;
    if old.deleted_at is not null then
      raise exception 'deleted listings are immutable';
    end if;
  end if;
  return new;
end;
$$;

revoke all on function public.listings_before_update() from public;

create trigger listings_before_update
before update on public.listings
for each row execute function public.listings_before_update();

-- ---------------------------------------------------------------------------
-- Grants / revokes
-- ---------------------------------------------------------------------------

-- moderators is fully closed to the app; only the SECURITY DEFINER helper reads it.
revoke all on public.moderators from anon, authenticated;

-- listings: anon may only read (RLS limits rows), authenticated may read/insert/update.
grant select on public.listings to anon;
grant select, insert, update on public.listings to authenticated;
revoke delete, truncate, references, trigger on public.listings from anon, authenticated;
grant usage on sequence public.listings_id_seq to authenticated;
