  if old.status = 'booked'
     and new.status = 'cancelled'
     and old.user_id = auth.uid()
     and old.reserved_for > now() then
    return new;
  end if;

  if old.status = 'booked'
     and new.status in ('seated', 'no_show')
     and public.is_restaurant_staff(old.restaurant_id)
     and old.reserved_for <= now() then
    return new;
  end if;

  raise exception 'Reservation update not allowed';
end;
