on public.files
for select
to authenticated
using (
  owner_id = (select auth.uid())
  or public.is_org_admin()
);

-- R2/R4: users upload only as themselves, and never with a legal hold.
create policy files_insert
on public.files
for insert
to authenticated
with check (
  owner_id = (select auth.uid())
  and legal_hold = false
);

-- R2/R3/R4: owners and admins may rename; rows under legal hold are
-- invisible to UPDATE (USING), and legal_hold can never be set to true
-- nor flipped back to false (WITH CHECK).
create policy files_update
on public.files
for update
to authenticated
using (
  (owner_id = (select auth.uid()) or public.is_org_admin())
  and legal_hold = false
)
with check (
  legal_hold = false
  and (owner_id = (select auth.uid()) or public.is_org_admin())
);

-- R2/R3: owners and admins may delete; legal holds block deletes.
create policy files_delete
on public.files
for delete
to authenticated
using (
  (owner_id = (select auth.uid()) or public.is_org_admin())
  and legal_hold = false
);

-- R3/R4 (defense in depth): block legal-hold and ownership mutations from
-- the app even if a policy were ever loosened. Service role is exempt so
-- the legal team's server tool keeps working (R7).
create or replace function public.files_guard_update()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if coalesce(auth.role(), '') = 'service_role' then
    return new;
  end if;

  if old.legal_hold then
    raise exception 'file % is under legal hold', old.id using errcode = '42501';
  end if;

  if new.legal_hold is distinct from old.legal_hold then
    raise exception 'legal_hold cannot be changed through the app' using errcode = '42501';
  end if;

  if new.owner_id is distinct from old.owner_id then
    raise exception 'owner_id cannot be changed' using errcode = '42501';
  end if;

  return new;
end;
$$;

