  if new.legal_hold is distinct from old.legal_hold then
    raise exception 'legal_hold can only be changed by the legal team'
      using errcode = '42501';
  end if;
  if new.owner_id is distinct from old.owner_id then
    raise exception 'owner_id is immutable'
