-- Helper: is the parent incident published? SECURITY DEFINER so the check
-- does not depend on the caller's RLS visibility of public.incidents.
create or replace function public.is_incident_published(p_incident_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.incidents i
    where i.id = p_incident_id
      and i.is_published
  );
$$;

