create or replace function public.enforce_ride_booking_update()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  confirmed_count integer;
  ride_seats integer;
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.ride_id is distinct from old.ride_id
     or new.passenger_id is distinct from old.passenger_id then
    raise exception 'ride_id and passenger_id cannot be changed';
  end if;

  if old.status <> 'requested' then
    raise exception 'only requested bookings can be answered';
  end if;

  if new.status not in ('confirmed', 'declined') then
    raise exception 'status must be confirmed or declined';
  end if;

  if new.status = 'confirmed' then
    select seats into ride_seats
    from public.rides
    where id = new.ride_id
    for update;

    if ride_seats is null then
      raise exception 'ride not found';
    end if;

    select count(*) into confirmed_count
    from public.ride_bookings
    where ride_id = new.ride_id
      and status = 'confirmed';

    if confirmed_count >= ride_seats then
      raise exception 'ride is full';
    end if;
  end if;

  return new;
end;
$$;

