alter table public.guardians enable row level security;
alter table public.grades enable row level security;

-- ---------------------------------------------------------------------------
-- Helper functions (SECURITY DEFINER so policy checks never recurse into RLS)
-- ---------------------------------------------------------------------------
create or replace function public.is_class_teacher(p_class_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.classes c
    where c.id = p_class_id
      and c.teacher_id = auth.uid()
  );
$$;

create or replace function public.is_enrolled(p_class_id bigint, p_student_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.class_students cs
    where cs.class_id = p_class_id
      and cs.student_id = p_student_id
  );
$$;

create or replace function public.is_guardian_of(p_student_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.guardians g
    where g.guardian_id = auth.uid()
      and g.student_id = p_student_id
  );
$$;

-- ---------------------------------------------------------------------------
-- Trigger: teachers always grade as themselves
-- ---------------------------------------------------------------------------
create or replace function public.grades_set_graded_by()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if auth.uid() is not null then
    new.graded_by := auth.uid();
  end if;
  return new;
end;
$$;

create trigger grades_set_graded_by
before insert or update on public.grades
for each row execute function public.grades_set_graded_by();

-- ---------------------------------------------------------------------------
-- public.classes
-- ---------------------------------------------------------------------------
create policy classes_select_authenticated
on public.classes
for select
to authenticated
using (true);

-- ---------------------------------------------------------------------------
-- public.class_students
-- ---------------------------------------------------------------------------
create policy class_students_select_own_or_teacher
on public.class_students
for select
to authenticated
using (
  student_id = auth.uid()
  or public.is_class_teacher(class_id)
);

-- ---------------------------------------------------------------------------
-- public.guardians
-- ---------------------------------------------------------------------------
create policy guardians_select_involved
on public.guardians
for select
to authenticated
using (
  guardian_id = auth.uid()
  or student_id = auth.uid()
);

-- ---------------------------------------------------------------------------
-- public.grades
-- ---------------------------------------------------------------------------
create policy grades_select_own_guardian_teacher
on public.grades
for select
to authenticated
using (
  student_id = auth.uid()
  or public.is_guardian_of(student_id)
  or public.is_class_teacher(class_id)
);

create policy grades_insert_teacher
on public.grades
for insert
to authenticated
with check (
  graded_by = auth.uid()
  and public.is_class_teacher(class_id)
  and public.is_enrolled(class_id, student_id)
);

create policy grades_update_teacher
on public.grades
for update
to authenticated
using (
  public.is_class_teacher(class_id)
)
with check (
  graded_by = auth.uid()
  and public.is_class_teacher(class_id)
  and public.is_enrolled(class_id, student_id)
);

create policy grades_delete_teacher
on public.grades
for delete
to authenticated
using (
  public.is_class_teacher(class_id)
);

-- ---------------------------------------------------------------------------
-- Grants / revokes
-- ---------------------------------------------------------------------------
revoke all on public.classes from anon;
revoke all on public.class_students from anon;
revoke all on public.guardians from anon;
revoke all on public.grades from anon;
revoke all on sequence public.grades_id_seq from anon;

grant select on public.classes to authenticated;
grant select on public.class_students to authenticated;
grant select on public.guardians to authenticated;
grant select, insert, update, delete on public.grades to authenticated;
grant usage, select on sequence public.grades_id_seq to authenticated;

grant all on public.classes to service_role;
grant all on public.class_students to service_role;
grant all on public.guardians to service_role;
grant all on public.grades to service_role;
grant all on sequence public.grades_id_seq to service_role;

revoke all on function public.is_class_teacher(bigint) from public;
revoke all on function public.is_enrolled(bigint, uuid) from public;
revoke all on function public.is_guardian_of(uuid) from public;
revoke all on function public.grades_set_graded_by() from public;

revoke all on function public.is_class_teacher(bigint) from anon;
revoke all on function public.is_enrolled(bigint, uuid) from anon;
revoke all on function public.is_guardian_of(uuid) from anon;
revoke all on function public.grades_set_graded_by() from anon;

