create function public.approve_access(p_request_id bigint)
returns text
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_caller uuid := auth.uid();
  v_request public.access_requests%rowtype;
  v_approval_count integer;
  v_status text;
begin
  if v_caller is null then
    raise exception 'not authenticated';
  end if;

  if not exists (
    select 1
    from public.ops_team ot
    where ot.user_id = v_caller
  ) then
    raise exception 'caller is not on the ops team';
  end if;

  select *
  into v_request
  from public.access_requests
  where id = p_request_id
  for update;

  if not found then
    raise exception 'request does not exist';
  end if;

  if v_request.status <> 'pending' then
    raise exception 'request is not pending';
  end if;

  if v_request.requester_id = v_caller then
    raise exception 'caller cannot approve their own request';
  end if;

  if exists (
    select 1
    from public.access_approvals aa
    where aa.request_id = p_request_id
      and aa.approver_id = v_caller
  ) then
    raise exception 'caller has already approved this request';
  end if;

  insert into public.access_approvals (request_id, approver_id)
  values (p_request_id, v_caller);

  select count(distinct aa.approver_id)
  into v_approval_count
  from public.access_approvals aa
  join public.ops_team ot
    on ot.user_id = aa.approver_id
  where aa.request_id = p_request_id;

  if v_approval_count >= 2 then
    update public.access_requests
    set status = 'granted'
    where id = p_request_id
    returning status into v_status;
  else
    v_status := 'pending';
  end if;

  return v_status;
end;
$$;

