    raise exception 'Not an ops team member';
  end if;

  select requester_id, status into v_requester, v_status
  from public.access_requests
  where id = p_request_id
  for update;

  if not found then
    raise exception 'Request % does not exist', p_request_id;
  end if;

  if v_status <> 'pending' then
    raise exception 'Request % is not pending', p_request_id;
