grant all on public.recipes to service_role;
grant all on public.favorites to service_role;
grant usage, select on sequence public.recipes_id_seq to service_role;

-- R1: anyone can read public recipes; authors can also read their own private ones.
create policy "recipes_select_public_or_own"
on public.recipes
for select
to anon, authenticated
using (is_public or author_id = auth.uid());

-- R2: signed-in users may create recipes only as themselves.
create policy "recipes_insert_as_self"
on public.recipes
for insert
to authenticated
with check (author_id = auth.uid());

-- R2: authors may edit their own recipes and can never hand them to another author.
create policy "recipes_update_own"
on public.recipes
for update
to authenticated
using (author_id = auth.uid())
with check (author_id = auth.uid());

-- R2: authors may delete their own recipes.
create policy "recipes_delete_own"
on public.recipes
for delete
to authenticated
using (author_id = auth.uid());

-- R3: users see only their own favourites.
create policy "favorites_select_own"
on public.favorites
for select
to authenticated
using (user_id = auth.uid());

-- R4: users may favourite only recipes they can read, and only as themselves.
create policy "favorites_insert_own_readable_recipe"
on public.favorites
for insert
to authenticated
with check (
  user_id = auth.uid()
  and exists (
    select 1
    from public.recipes r
    where r.id = recipe_id
      and (r.is_public or r.author_id = auth.uid())
  )
);

-- R4: users may remove only their own favourites.
create policy "favorites_delete_own"
on public.favorites
for delete
to authenticated
using (user_id = auth.uid());

-- R2 (defence in depth): author_id is immutable once set, even for privileged paths
-- that do not go through the update policy's WITH CHECK.
create or replace function public.recipes_lock_author_id()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if new.author_id is distinct from old.author_id then
    raise exception 'recipes.author_id is immutable' using errcode = '42501';
  end if;
  return new;
end;
$$;

create trigger recipes_lock_author_id
before update on public.recipes
for each row
execute function public.recipes_lock_author_id();
