-- unprotected and record themselves); editors may edit any page and may
-- protect/unprotect.
create policy pages_update_authenticated on public.pages
  for update to authenticated
  using (
    not is_protected or public.is_editor(auth.uid())
  )
  with check (
    updated_by = auth.uid()
