create function public.is_pharmacist()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.pharmacists
    where user_id = auth.uid()
  );
$$;

create function public.dispense(p_prescription_id bigint)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_patient_id uuid;
  v_refills_left integer;
  v_expires_at timestamptz;
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;

  if not exists (
    select 1
    from public.pharmacists
    where user_id = v_uid
  ) then
    raise exception 'Caller is not a pharmacist' using errcode = '42501';
  end if;

  select patient_id, refills_left, expires_at
    into v_patient_id, v_refills_left, v_expires_at
    from public.prescriptions
   where id = p_prescription_id
   for update;

  if not found then
    raise exception 'Prescription does not exist' using errcode = 'P0002';
  end if;

  if v_patient_id = v_uid then
    raise exception 'Pharmacist cannot dispense their own prescription' using errcode = '42501';
  end if;

  if v_expires_at <= now() then
    raise exception 'Prescription has expired' using errcode = '22000';
  end if;

  if v_refills_left <= 0 then
    raise exception 'Prescription has no refills left' using errcode = '22000';
  end if;

  update public.prescriptions
     set refills_left = refills_left - 1
   where id = p_prescription_id
   returning refills_left into v_refills_left;

  insert into public.dispenses (prescription_id, pharmacist_id, dispensed_at)
  values (p_prescription_id, v_uid, now());

  return v_refills_left;
end;
$$;

create policy "Authenticated users can view pharmacists"
on public.pharmacists
for select
to authenticated
using (auth.uid() is not null);

create policy "Patients and pharmacists can view prescriptions"
on public.prescriptions
for select
to authenticated
using (
  patient_id = auth.uid()
  or public.is_pharmacist()
);

create policy "Patients and pharmacists can view dispenses"
on public.dispenses
for select
to authenticated
using (
  public.is_pharmacist()
  or exists (
    select 1
    from public.prescriptions p
    where p.id = dispenses.prescription_id
      and p.patient_id = auth.uid()
  )
);

revoke all on public.pharmacists from anon, authenticated;
revoke all on public.prescriptions from anon, authenticated;
revoke all on public.dispenses from anon, authenticated;

grant select on public.pharmacists to authenticated;
