```sql
alter table public.orgs enable row level security;
alter table public.org_members enable row level security;
alter table public.org_documents enable row level security;

-- Session proof: SSO is proven ONLY by an `amr` entry with method 'sso/saml'.
-- auth.jwt() is signed by Supabase, so user_metadata cannot influence this.
create or replace function public.has_sso_session()
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from jsonb_array_elements(
      case
        when jsonb_typeof(auth.jwt() -> 'amr') = 'array' then auth.jwt() -> 'amr'
        else '[]'::jsonb
      end
    ) as entry
    where entry ->> 'method' = 'sso/saml'
  );
$$;

-- Membership / admin checks run as definer so they are not subject to RLS
-- recursion on public.org_members.
create or replace function public.is_org_member(p_org_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.org_members m
    where m.org_id = p_org_id
      and m.user_id = auth.uid()
  );
$$;

create or replace function public.is_org_admin(p_org_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.org_members m
    where m.org_id = p_org_id
      and m.user_id = auth.uid()
      and m.role = 'admin'
  );
$$;

-- An org's content is visible/actionable only when either the org does not
-- require SSO, or the current session is an SSO session.
create or replace function public.org_session_ok(p_org_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.orgs o
    where o.id = p_org_id
      and (o.require_sso is not true or public.has_sso_session())
  );
$$;

revoke all on function public.has_sso_session() from public;
revoke all on function public.is_org_member(bigint) from public;
revoke all on function public.is_org_admin(bigint) from public;
revoke all on function public.org_session_ok(bigint) from public;

grant execute on function public.has_sso_session() to authenticated, service_role;
grant execute on function public.is_org_member(bigint) to authenticated, service_role;
grant execute on function public.is_org_admin(bigint) to authenticated, service_role;
grant execute on function public.org_session_ok(bigint) to authenticated, service_role;

-- R1 / R3: members see their orgs; admins update settings (same session gate).
create policy orgs_select_members
  on public.orgs
  for select
  to authenticated
  using (
    public.is_org_member(id)
    and public.org_session_ok(id)
  );

create policy orgs_update_admins
  on public.orgs
  for update
  to authenticated
  using (
    public.is_org_admin(id)
    and public.org_session_ok(id)
  )
  with check (
    public.is_org_admin(id)
    and public.org_session_ok(id)
  );

-- R1 / R4: members see the roster of their own orgs; nobody writes memberships
-- through the API (no insert/update/delete policies at all).
create policy org_members_select_members
  on public.org_members
  for select
  to authenticated
  using (
    public.is_org_member(org_id)
    and public.org_session_ok(org_id)
  );

-- R1 / R2: members read documents, admins write them, all behind the SSO gate.
create policy org_documents_select_members
  on public.org_documents
  for select
  to authenticated
  using (
    public.is_org_member(org_id)
    and public.org_session_ok(org_id)
  );

create policy org_documents_insert_admins
  on public.org_documents
  for insert
  to authenticated
  with check (
    public.is_org_admin(org_id)
    and public.org_session_ok(org_id)
  );

create policy org_documents_update_admins
  on public.org_documents
  for update
  to authenticated
  using (
    public.is_org_admin(org_id)
    and public.org_session_ok(org_id)
  )
  with check (
    public.is_org_admin(org_id)
    and public.org_session_ok(org_id)
  );

create policy org_documents_delete_admins
