-- R5: anonymous visitors get nothing.
revoke all on public.orgs from anon;
revoke all on public.org_members from anon;
revoke all on public.org_documents from anon;
revoke all on sequence public.org_documents_id_seq from anon;

-- R1 / R2 / R3: authenticated grants, narrowed to what policies allow.
grant select on public.orgs to authenticated;
grant update on public.orgs to authenticated;

grant select on public.org_members to authenticated;
revoke insert, update, delete on public.org_members from authenticated;

