-- Helper: does the current session's verified JWT prove an SSO (SAML) sign-in?
-- Only the signed `amr` claim is consulted; `user_metadata` is user-editable and ignored.
create or replace function public.jwt_has_sso_amr()
returns boolean
language sql
stable
security invoker
set search_path = ''
as $$
  select case
    when jsonb_typeof(auth.jwt() -> 'amr') = 'array' then
      exists (
        select 1
        from jsonb_array_elements(auth.jwt() -> 'amr') as e
        where (jsonb_typeof(e) = 'object' and e ->> 'method' = 'sso/saml')
           or (jsonb_typeof(e) = 'string' and e #>> '{}' = 'sso/saml')
      )
    when jsonb_typeof(auth.jwt() -> 'amr') = 'string' then
      (auth.jwt() ->> 'amr') = 'sso/saml'
    else false
  end;
$$;

-- Helper: membership checks that bypass RLS on org_members/orgs to avoid policy recursion.
create or replace function public.is_org_member(p_org_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.org_members m
    where m.org_id = p_org_id
      and m.user_id = auth.uid()
  );
$$;

create or replace function public.is_org_admin(p_org_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.org_members m
    where m.org_id = p_org_id
      and m.user_id = auth.uid()
      and m.role = 'admin'
  );
$$;

-- Helper: does this org permit the current session at all (SSO gate for require_sso orgs)?
create or replace function public.org_session_ok(p_org_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.orgs o
    where o.id = p_org_id
      and (o.require_sso = false or public.jwt_has_sso_amr())
  );
