create function public.dispense(p_prescription_id bigint)
returns integer
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_patient_id uuid;
  v_expires_at timestamptz;
  v_refills integer;
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;

  if not exists (
    select 1
    from public.pharmacists ph
    where ph.user_id = v_uid
  ) then
    raise exception 'Not a pharmacist' using errcode = '42501';
  end if;

  select p.patient_id, p.expires_at, p.refills_left
    into v_patient_id, v_expires_at, v_refills
  from public.prescriptions p
  where p.id = p_prescription_id
  for update;

  if not found then
    raise exception 'Prescription not found' using errcode = 'P0002';
  end if;

  if v_patient_id = v_uid then
    raise exception 'Cannot dispense own prescription' using errcode = '42501';
  end if;

  if v_expires_at <= now() then
    raise exception 'Prescription expired' using errcode = 'P0001';
  end if;

  if v_refills <= 0 then
    raise exception 'No refills left' using errcode = 'P0001';
  end if;

  update public.prescriptions
     set refills_left = refills_left - 1
   where id = p_prescription_id
   returning refills_left into v_refills;

  insert into public.dispenses (prescription_id, pharmacist_id)
  values (p_prescription_id, v_uid);

  return v_refills;
end;
$$;

