-- Proof of an SSO session comes ONLY from the signed JWT `amr` claim.
-- user_metadata is user-writable and is never consulted.
create or replace function public.jwt_has_sso()
returns boolean
language sql
stable
set search_path = ''
as $$
  select case
    when jsonb_typeof(auth.jwt() -> 'amr') = 'array' then
      exists (
        select 1
        from jsonb_array_elements(auth.jwt() -> 'amr') as amr_entry
        where jsonb_typeof(amr_entry) = 'object'
          and amr_entry ->> 'method' = 'sso/saml'
      )
    else false
  end;
$$;

create or replace function public.is_org_member(p_org_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.org_members m
    where m.org_id = p_org_id
      and m.user_id = auth.uid()
  );
$$;

create or replace function public.is_org_admin(p_org_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.org_members m
    where m.org_id = p_org_id
      and m.user_id = auth.uid()
      and m.role = 'admin'
  );
$$;

-- Session satisfies the organization's authentication requirement:
-- orgs without require_sso accept any authenticated session; orgs with
-- require_sso accept only sessions whose amr proves sso/saml.
create or replace function public.org_session_ok(p_org_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.orgs o
    where o.id = p_org_id
      and (o.require_sso = false or public.jwt_has_sso())
  );
$$;

