create or replace function public.checkout_document(p_doc_id bigint)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_checked_out_by uuid;
  v_can_edit boolean;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  select checked_out_by into v_checked_out_by
  from public.documents
  where id = p_doc_id
  for update;

  if not found then
    raise exception 'document % not found', p_doc_id;
  end if;

  select can_edit into v_can_edit
  from public.doc_access
  where doc_id = p_doc_id and user_id = v_uid;

  if not coalesce(v_can_edit, false) then
    raise exception 'no edit access to document %', p_doc_id;
  end if;

  if v_checked_out_by is not null and v_checked_out_by <> v_uid then
    raise exception 'document % is checked out by another user', p_doc_id;
  end if;

  update public.documents
  set checked_out_by = v_uid
  where id = p_doc_id;
end;
$$;

