  v_uid uuid := auth.uid();
  v_checked_out_by uuid;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  select checked_out_by into v_checked_out_by
  from public.documents
  where id = p_doc_id
  for update;

  if not found then
    raise exception 'document % not found', p_doc_id;
  end if;

  if v_checked_out_by is distinct from v_uid then
    raise exception 'document % is not checked out by you', p_doc_id;
  end if;

  update public.documents
  set body = p_body, checked_out_by = null
  where id = p_doc_id;
