-- ============================================================
-- Helper functions
-- ============================================================

-- True only when the *signed* JWT `amr` claim contains an SSO/SAML method.
-- user_metadata is never consulted.
create or replace function public.jwt_has_sso()
returns boolean
language plpgsql
stable
set search_path = ''
as $$
declare
  amr jsonb;
begin
  amr := (auth.jwt())::jsonb -> 'amr';
  if amr is null or jsonb_typeof(amr) <> 'array' then
    return false;
  end if;
  return exists (
    select 1
    from jsonb_array_elements(amr) as e
    where e ->> 'method' = 'sso/saml'
  );
end;
$$;

-- Membership lookup (security definer to avoid RLS recursion on org_members).
create or replace function public.is_org_member(p_org_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.org_members m
    where m.org_id = p_org_id
      and m.user_id = auth.uid()
  );
$$;

-- Admin lookup (security definer to avoid RLS recursion).
create or replace function public.is_org_admin(p_org_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.org_members m
    where m.org_id = p_org_id
      and m.user_id = auth.uid()
      and m.role = 'admin'
  );
$$;

-- Session gate for an org: OK unless the org requires SSO, in which case
-- the current session must be an SSO/SAML session. Missing org => false.
create or replace function public.org_session_ok(p_org_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
    (
      select case when o.require_sso then public.jwt_has_sso() else true end
      from public.orgs o
      where o.id = p_org_id
    ),
    false
  );
$$;

