alter table public.api_usage enable row level security;

-- R3 / R4: no write access for app roles, no access at all for anon
revoke all on table public.api_usage from anon;
revoke all on table public.api_usage from public;
revoke insert, update, delete, truncate on table public.api_usage from authenticated;
grant select on table public.api_usage to authenticated;
grant all on table public.api_usage to service_role;

-- R1: users read only their own rows
create policy "api_usage_select_own"
  on public.api_usage
  for select
  to authenticated
  using (user_id = (select auth.uid()));

-- R2 / R5: per-user summary; security_invoker makes underlying RLS apply,
-- so authenticated users see only their own row while service_role sees all.
create view public.usage_summary
with (security_invoker = true)
as
select
  user_id,
  sum(requests)::bigint as total_requests,
  count(*)::bigint      as active_days
from public.api_usage
group by user_id;

revoke all on table public.usage_summary from anon;
revoke all on table public.usage_summary from public;
grant select on table public.usage_summary to authenticated;
grant select on table public.usage_summary to service_role;
