```sql
alter table public.units enable row level security;
alter table public.residents enable row level security;
alter table public.building_staff enable row level security;
alter table public.requests enable row level security;
alter table public.request_photos enable row level security;

-- ---------------------------------------------------------------------------
-- Helper functions (SECURITY DEFINER so they bypass RLS and cannot recurse)
-- ---------------------------------------------------------------------------
create or replace function public.is_unit_resident(p_unit_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.residents r
    where r.unit_id = p_unit_id
      and r.user_id = auth.uid()
  );
$$;

create or replace function public.is_building_staff(p_building_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.building_staff s
    where s.building_id = p_building_id
      and s.user_id = auth.uid()
  );
$$;

create or replace function public.is_staff_of_unit(p_unit_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.units u
    join public.building_staff s on s.building_id = u.building_id
    where u.id = p_unit_id
      and s.user_id = auth.uid()
  );
$$;

create or replace function public.can_access_unit(p_unit_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select public.is_unit_resident(p_unit_id) or public.is_staff_of_unit(p_unit_id);
$$;

create or replace function public.can_access_request(p_request_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.requests rq
    where rq.id = p_request_id
      and (public.is_unit_resident(rq.unit_id) or public.is_staff_of_unit(rq.unit_id))
  );
$$;

-- ---------------------------------------------------------------------------
-- units: read-only for residents of the unit and staff of the building
-- ---------------------------------------------------------------------------
create policy units_select on public.units
  for select to authenticated
  using (public.can_access_unit(id));

-- ---------------------------------------------------------------------------
-- residents: users see only their own residence rows; no writes
-- ---------------------------------------------------------------------------
create policy residents_select on public.residents
  for select to authenticated
  using (user_id = auth.uid());

-- ---------------------------------------------------------------------------
-- building_staff: users see only their own staff rows; no writes
-- ---------------------------------------------------------------------------
create policy building_staff_select on public.building_staff
  for select to authenticated
  using (user_id = auth.uid());

-- ---------------------------------------------------------------------------
-- requests
-- ---------------------------------------------------------------------------
create policy requests_select on public.requests
  for select to authenticated
  using (public.can_access_unit(unit_id));

create policy requests_insert on public.requests
  for insert to authenticated
  with check (
    created_by = auth.uid()
    and status = 'open'
    and public.is_unit_resident(unit_id)
  );

create policy requests_update_staff on public.requests
  for update to authenticated
  using (public.is_staff_of_unit(unit_id))
  with check (public.is_staff_of_unit(unit_id));

-- ---------------------------------------------------------------------------
-- request_photos
-- ---------------------------------------------------------------------------
create policy request_photos_select on public.request_photos
  for select to authenticated
  using (public.can_access_request(request_id));

create policy request_photos_insert on public.request_photos
  for insert to authenticated
  with check (public.can_access_request(request_id));

-- ---------------------------------------------------------------------------
-- Trigger: only `status` may ever change on a request, and only by staff
-- (skipped for non-`authenticated` roles so service_role keeps full access)
-- ---------------------------------------------------------------------------
create or replace function public.requests_enforce_status_only()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  if current_user <> 'authenticated' then
    return new;
  end if;

  if new.id is distinct from old.id
     or new.unit_id is distinct from old.unit_id
     or new.created_by is distinct from old.created_by
     or new.description is distinct from old.description then
    raise exception 'Only the status of a request may be changed';
  end if;

  if new.status is distinct from old.status
     and not public.is_staff_of_unit(old.unit_id) then
    raise exception 'Only building staff may change request status';
  end if;

  return new;
end;
$$;

create trigger requests_enforce_status_only
  before update on public.requests
  for each row execute function public.requests_enforce_status_only();

-- ---------------------------------------------------------------------------
-- Grants / revokes
-- ---------------------------------------------------------------------------
revoke all on public.units, public.residents, public.building_staff,
              public.requests, public.request_photos from anon;
revoke all on public.units, public.residents, public.building_staff,
              public.requests, public.request_photos from public;

grant select on public.units to authenticated;
grant select on public.residents to authenticated;
grant select on public.building_staff to authenticated;
grant select, insert on public.requests to authenticated;
grant update (status) on public.requests to authenticated;
grant select, insert on public.request_photos to authenticated;

revoke all on function public.is_unit_resident(bigint) from public;
revoke all on function public.is_building_staff(bigint) from public;
revoke all on function public.is_staff_of_unit(bigint) from public;
revoke all on function public.can_access_unit(bigint) from public;
revoke all on function public.can_access_request(bigint) from public;

grant execute on function public.is_unit_resident(bigint) to authenticated;
grant execute on function public.is_building_staff(bigint) to authenticated;
grant execute on function public.is_staff_of_unit(bigint) to authenticated;
grant execute on function public.can_access_unit(bigint) to authenticated;
grant execute on function public.can_access_request(bigint) to authenticated;
```

