set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;
  if new.id <> old.id
     or new.course_id <> old.course_id
     or new.created_by <> old.created_by
     or new.title <> old.title then
    raise exception 'threads: only the lock state may be modified';
