create or replace function public.can_claim_item(p_item_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1 from public.items i
    where i.id = p_item_id
      and i.status = 'open'
      and i.found_by <> auth.uid()
  );
$$;

-- Integrity triggers ------------------------------------------------------

create or replace function public.enforce_claim_insert()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if new.status is distinct from 'pending' then
    raise exception 'new claims must be pending';
  end if;
  if new.claimant_id is distinct from auth.uid() then
    raise exception 'claims must be filed as the current user';
  end if;
  return new;
end;
$$;

create or replace function public.enforce_claim_update()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if new.item_id is distinct from old.item_id
     or new.claimant_id is distinct from old.claimant_id
     or new.message is distinct from old.message then
    raise exception 'only the claim status may be changed';
  end if;

  if new.status is distinct from old.status then
    if old.status <> 'pending' then
      raise exception 'only pending claims can be resolved';
    end if;
    if new.status not in ('approved', 'rejected') then
      raise exception 'invalid claim status transition';
    end if;
  end if;

  if new.status = 'approved' then
    if exists (
      select 1 from public.claims c
      where c.item_id = new.item_id
        and c.status = 'approved'
        and c.id <> new.id
    ) then
      raise exception 'item already has an approved claim';
    end if;
  end if;

  return new;
end;
$$;

create trigger claims_enforce_insert
before insert on public.claims
for each row execute function public.enforce_claim_insert();

create trigger claims_enforce_update
before update on public.claims
for each row execute function public.enforce_claim_update();

