to authenticated
with check (
  claimant_id = auth.uid()
  and status = 'pending'
  and public.can_claim_item(item_id)
);

create policy claims_update_finder
on public.claims for update
to authenticated
using (status = 'pending' and public.is_item_finder(item_id))
with check (
  status in ('approved', 'rejected')
  and public.is_item_finder(item_id)
);

