  on public.items
  for update
  to authenticated
  using (found_by = auth.uid())
  with check (found_by = auth.uid());

-- ============================================================
-- claims policies (R2, R3, R4, R5)
-- ============================================================
create policy claims_select_own_or_finder
  on public.claims
  for select
  to authenticated
  using (
    claimant_id = auth.uid()
    or public.is_item_finder(item_id)
  );

