  on public.claims
  for insert
  to authenticated
  with check (
    claimant_id = auth.uid()
    and status = 'pending'
    and public.item_status(item_id) = 'open'
    and public.item_finder(item_id) is not null
    and public.item_finder(item_id) <> auth.uid()
  );

create policy claims_update_finder_decides_pending
  on public.claims
  for update
  to authenticated
  using (
    public.is_item_finder(item_id)
    and status = 'pending'
  )
  with check (
    public.is_item_finder(item_id)
    and status in ('approved', 'rejected')
  );

-- ============================================================
-- claims guard trigger: immutability, status transitions,
-- single approved claim per item (R4). Service role bypasses.
-- ============================================================
create or replace function public.claims_guard()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if coalesce(auth.role(), '') = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.status is distinct from 'pending' then
      raise exception 'new claims must be pending';
    end if;
  else
    if new.id          is distinct from old.id
       or new.item_id  is distinct from old.item_id
       or new.claimant_id is distinct from old.claimant_id
       or new.message  is distinct from old.message then
      raise exception 'only the claim status may be changed';
    end if;

    if new.status is distinct from old.status then
      if old.status <> 'pending'
         or new.status not in ('approved', 'rejected') then
        raise exception 'invalid claim status transition';
      end if;

      if not exists (
        select 1 from public.items i
        where i.id = old.item_id and i.found_by = auth.uid()
      ) then
        raise exception 'only the finder can approve or reject a claim';
      end if;
    end if;
  end if;

  if new.status = 'approved' and exists (
    select 1 from public.claims c
    where c.item_id = new.item_id
      and c.status = 'approved'
      and c.id <> new.id
  ) then
    raise exception 'item already has an approved claim';
  end if;

  return new;
end;
$$;

revoke all on function public.claims_guard() from public, anon;
grant execute on function public.claims_guard() to authenticated, service_role;

create trigger claims_guard
  before insert or update on public.claims
  for each row
  execute function public.claims_guard();

