alter table public.listings enable row level security;
alter table public.orders enable row level security;

-- R1: signed-in users can see every listing
create policy listings_select_authenticated
  on public.listings
  for select
  to authenticated
  using (true);

-- R1: buyers and sellers can see the orders they are part of
create policy orders_select_participant
  on public.orders
  for select
  to authenticated
  using (buyer_id = auth.uid() or seller_id = auth.uid());

-- R2: buyers place orders as themselves, matching the listing's seller and price,
-- always starting in pending_payment, and never on their own listing
create policy orders_insert_buyer
  on public.orders
  for insert
  to authenticated
  with check (
    buyer_id = auth.uid()
    and status = 'pending_payment'
    and exists (
      select 1
      from public.listings l
      where l.id = orders.listing_id
        and l.seller_id = orders.seller_id
        and l.price = orders.amount
        and l.seller_id <> auth.uid()
    )
  );

-- R3: no update/delete policies on orders (and no write policies on listings),
-- so direct mutations through the app are denied. Status changes go through
-- the SECURITY DEFINER functions below (or service_role server code).

-- R4/R5: mark_shipped
create or replace function public.mark_shipped(p_order_id bigint)
returns text
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_seller uuid;
  v_status text;
begin
  select seller_id, status
    into v_seller, v_status
    from public.orders
   where id = p_order_id
     for update;

  if not found then
    raise exception 'order % not found', p_order_id using errcode = 'P0002';
  end if;

  if v_seller is distinct from auth.uid() then
    raise exception 'only the seller may mark this order shipped' using errcode = '42501';
  end if;

  if v_status <> 'paid' then
    raise exception 'order % is in status %, expected paid', p_order_id, v_status using errcode = '22000';
  end if;

  update public.orders set status = 'shipped' where id = p_order_id;
  return 'shipped';
end;
$$;

-- R4/R5: release_funds
create or replace function public.release_funds(p_order_id bigint)
returns text
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_buyer uuid;
  v_status text;
begin
  select buyer_id, status
    into v_buyer, v_status
    from public.orders
   where id = p_order_id
     for update;

  if not found then
    raise exception 'order % not found', p_order_id using errcode = 'P0002';
  end if;

  if v_buyer is distinct from auth.uid() then
    raise exception 'only the buyer may release funds for this order' using errcode = '42501';
  end if;

  if v_status <> 'shipped' then
    raise exception 'order % is in status %, expected shipped', p_order_id, v_status using errcode = '22000';
  end if;

  update public.orders set status = 'released' where id = p_order_id;
  return 'released';
end;
$$;

-- R4/R5: refund_order
create or replace function public.refund_order(p_order_id bigint)
returns text
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_seller uuid;
  v_status text;
begin
  select seller_id, status
    into v_seller, v_status
    from public.orders
   where id = p_order_id
     for update;

  if not found then
    raise exception 'order % not found', p_order_id using errcode = 'P0002';
  end if;

  if v_seller is distinct from auth.uid() then
    raise exception 'only the seller may refund this order' using errcode = '42501';
  end if;

  if v_status not in ('paid', 'shipped') then
    raise exception 'order % is in status %, expected paid or shipped', p_order_id, v_status using errcode = '22000';
  end if;

  update public.orders set status = 'refunded' where id = p_order_id;
  return 'refunded';
end;
$$;

-- R6: anonymous visitors get nothing
revoke all on public.listings from anon;
revoke all on public.orders from anon;

-- R3: authenticated users may only read listings and read/insert orders
revoke insert, update, delete on public.listings from authenticated;
revoke update, delete on public.orders from authenticated;
grant select on public.listings to authenticated;
grant select, insert on public.orders to authenticated;

-- R4/R5: only signed-in users may call the transition functions
revoke all on function public.mark_shipped(bigint) from public, anon;
revoke all on function public.release_funds(bigint) from public, anon;
revoke all on function public.refund_order(bigint) from public, anon;
grant execute on function public.mark_shipped(bigint) to authenticated;
grant execute on function public.release_funds(bigint) to authenticated;
