```sql
alter table public.journal_entries enable row level security;

-- R3: created_at (and identity/ownership columns) are immutable from the client's perspective.
create or replace function public.journal_entries_force_immutable_columns()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    new.created_at := now();
  elsif tg_op = 'UPDATE' then
    new.id := old.id;
    new.user_id := old.user_id;
    new.created_at := old.created_at;
  end if;
  return new;
end;
$$;

create trigger journal_entries_force_immutable_columns
before insert or update on public.journal_entries
for each row
execute function public.journal_entries_force_immutable_columns();

-- Helper: is the current user allowed to edit/delete the given entry (24h window)?
create or replace function public.journal_entries_is_editable(entry_user_id uuid, entry_created_at timestamptz)
returns boolean
language sql
stable
security invoker
set search_path = ''
as $$
  select entry_user_id = auth.uid()
     and entry_created_at > now() - interval '24 hours';
$$;

-- R1: read own entries only.
create policy "journal_entries_select_own"
on public.journal_entries
for select
to authenticated
using (auth.uid() = user_id);

-- R1: insert only for self.
create policy "journal_entries_insert_own"
on public.journal_entries
for insert
to authenticated
with check (auth.uid() = user_id);

-- R1 + R2: update own entries within 24 hours of created_at.
create policy "journal_entries_update_own_within_24h"
on public.journal_entries
for update
to authenticated
using (public.journal_entries_is_editable(user_id, created_at))
with check (public.journal_entries_is_editable(user_id, created_at));

-- R1 + R2: delete own entries within 24 hours of created_at.
create policy "journal_entries_delete_own_within_24h"
on public.journal_entries
for delete
to authenticated
using (public.journal_entries_is_editable(user_id, created_at));

-- R4: anonymous visitors get nothing.
revoke all on public.journal_entries from anon;
revoke all on sequence public.journal_entries_id_seq from anon;

-- Client roles: least privilege, column-level for insert/update so created_at can never be written.
revoke all on public.journal_entries from authenticated;
grant select on public.journal_entries to authenticated;
grant insert (user_id, body, mood) on public.journal_entries to authenticated;
grant update (body, mood) on public.journal_entries to authenticated;
grant delete on public.journal_entries to authenticated;
grant usage on sequence public.journal_entries_id_seq to authenticated;

-- R5: service role keeps full access.
grant all on public.journal_entries to service_role;
grant all on sequence public.journal_entries_id_seq to service_role;
