returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    new.created_at := now();
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if new.created_at is distinct from old.created_at then
