alter table public.journal_entries enable row level security;

-- R3: created_at is always the time of writing; users may never set or change it.
create or replace function public.journal_entries_force_created_at()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    if coalesce(auth.role(), '') <> 'service_role' then
      new.created_at := pg_catalog.now();
    end if;
    return new;
  elsif tg_op = 'UPDATE' then
    if coalesce(auth.role(), '') <> 'service_role' then
      new.created_at := old.created_at;
    end if;
    return new;
  end if;
  return new;
end;
$$;

create trigger journal_entries_force_created_at
before insert or update on public.journal_entries
for each row
execute function public.journal_entries_force_created_at();

-- R1 / R4: only authenticated users, only their own rows.
create policy "journal_entries_select_own"
on public.journal_entries
for select
to authenticated
using (user_id = auth.uid());

-- R1 / R4: inserts must be attributed to the caller.
create policy "journal_entries_insert_own"
on public.journal_entries
for insert
to authenticated
with check (user_id = auth.uid());

-- R1 / R2: edits only on own rows, only within 24 hours of creation.
create policy "journal_entries_update_own_recent"
on public.journal_entries
for update
to authenticated
using (
  user_id = auth.uid()
  and created_at > now() - interval '24 hours'
)
with check (user_id = auth.uid());

-- R1 / R2: deletes only on own rows, only within 24 hours of creation.
create policy "journal_entries_delete_own_recent"
on public.journal_entries
for delete
to authenticated
using (
  user_id = auth.uid()
  and created_at > now() - interval '24 hours'
);

-- R4: anonymous visitors get nothing.
revoke all on table public.journal_entries from public;
revoke all on table public.journal_entries from anon;
revoke all on sequence public.journal_entries_id_seq from public;
revoke all on sequence public.journal_entries_id_seq from anon;

