create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_auction public.auctions%rowtype;
  v_amount numeric(10, 2);
  v_min_required numeric(10, 2);
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;

  if p_auction_id is null then
    raise exception 'Auction id is required' using errcode = '22023';
  end if;

  if p_amount is null then
    raise exception 'Bid amount is required' using errcode = '22023';
  end if;

  v_amount := p_amount;

  select *
  into v_auction
  from public.auctions
  where id = p_auction_id
  for update;

  if not found then
    raise exception 'Auction does not exist' using errcode = 'P0002';
  end if;

  if v_auction.ends_at <= now() then
    raise exception 'Auction has ended' using errcode = 'P0001';
  end if;

  if v_auction.seller_id = v_uid then
    raise exception 'Sellers cannot bid on their own auctions' using errcode = 'P0001';
  end if;

  if v_auction.highest_bid is null then
    v_min_required := v_auction.starting_price;
  else
    v_min_required := v_auction.highest_bid + v_auction.min_increment;
  end if;

  if v_amount < v_min_required then
    raise exception 'Bid amount too low: minimum is %', v_min_required using errcode = 'P0001';
  end if;

  update public.auctions
  set highest_bid = v_amount,
      highest_bidder = v_uid
  where id = p_auction_id;

  insert into public.bids (auction_id, bidder_id, amount, placed_at)
  values (p_auction_id, v_uid, v_amount, now());

  return v_amount;
end;
$$;

revoke all on table public.auctions from anon, authenticated;
revoke all on table public.bids from anon, authenticated;
revoke all on sequence public.bids_id_seq from anon, authenticated;

