create or replace function public.sign_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_status text;
  v_sign_order integer;
  v_signed_at timestamptz;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;

  select e.status
    into v_status
    from public.envelopes e
   where e.id = p_envelope_id
     for update;

  if not found then
    raise exception 'envelope not found' using errcode = 'P0002';
  end if;

  select r.sign_order, r.signed_at
    into v_sign_order, v_signed_at
    from public.envelope_recipients r
   where r.envelope_id = p_envelope_id
     and r.user_id = v_uid;

  if not found then
    raise exception 'caller is not a recipient of this envelope' using errcode = '42501';
  end if;

  if v_signed_at is not null then
    raise exception 'recipient has already signed' using errcode = 'P0001';
  end if;

  if v_status <> 'sent' then
    raise exception 'envelope is not open for signing' using errcode = 'P0001';
  end if;

  if exists (
    select 1
      from public.envelope_recipients r
     where r.envelope_id = p_envelope_id
       and r.sign_order < v_sign_order
       and r.signed_at is null
  ) then
    raise exception 'an earlier recipient has not signed yet' using errcode = 'P0001';
  end if;

  update public.envelope_recipients
     set signed_at = now()
   where envelope_id = p_envelope_id
     and user_id = v_uid;

  if not exists (
    select 1
      from public.envelope_recipients r
     where r.envelope_id = p_envelope_id
       and r.signed_at is null
  ) then
    update public.envelopes
       set status = 'completed'
     where id = p_envelope_id;
    v_status := 'completed';
  end if;

  return v_status;
end;
$$;

