returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.envelopes e
    where e.id = p_envelope_id
      and (
        e.sender_id = auth.uid()
        or exists (
          select 1
          from public.envelope_recipients r
          where r.envelope_id = e.id
            and r.user_id = auth.uid()
        )
      )
  );
