-- R3: recipient signs in sign_order
create or replace function public.sign_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_status text;
  v_signed_at timestamptz;
  v_order integer;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  select e.status
    into v_status
    from public.envelopes e
   where e.id = p_envelope_id
   for update;

  if not found then
    raise exception 'envelope % not found', p_envelope_id;
  end if;

  select r.signed_at, r.sign_order
    into v_signed_at, v_order
    from public.envelope_recipients r
   where r.envelope_id = p_envelope_id
     and r.user_id = v_uid
   for update;

  if not found then
    raise exception 'caller is not a recipient of envelope %', p_envelope_id;
  end if;

  if v_signed_at is not null then
    raise exception 'recipient has already signed envelope %', p_envelope_id;
  end if;

  if v_status <> 'sent' then
    raise exception 'envelope % is not open for signing (status %)', p_envelope_id, v_status;
  end if;

  if exists (
    select 1
      from public.envelope_recipients r
     where r.envelope_id = p_envelope_id
       and r.sign_order < v_order
       and r.signed_at is null
  ) then
    raise exception 'an earlier recipient in sign_order has not signed envelope % yet', p_envelope_id;
  end if;

  update public.envelope_recipients
     set signed_at = now()
   where envelope_id = p_envelope_id
     and user_id = v_uid;

  if not exists (
    select 1
      from public.envelope_recipients r
     where r.envelope_id = p_envelope_id
       and r.signed_at is null
  ) then
    update public.envelopes
       set status = 'completed'
     where id = p_envelope_id;
    v_status := 'completed';
  end if;

  return v_status;
end;
$$;

-- R4: sender voids a still-'sent' envelope
create or replace function public.void_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_status text;
  v_sender_id uuid;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  select e.status, e.sender_id
    into v_status, v_sender_id
    from public.envelopes e
   where e.id = p_envelope_id
   for update;

  if not found then
    raise exception 'envelope % not found', p_envelope_id;
  end if;

  if v_sender_id <> v_uid then
    raise exception 'only the sender can void envelope %', p_envelope_id;
  end if;

  if v_status <> 'sent' then
    raise exception 'envelope % is not open for voiding (status %)', p_envelope_id, v_status;
  end if;

  update public.envelopes
     set status = 'voided'
   where id = p_envelope_id;

  return 'voided';
end;
$$;

revoke execute on function public.sign_envelope(bigint) from public, anon;
revoke execute on function public.void_envelope(bigint) from public, anon;

grant execute on function public.sign_envelope(bigint) to authenticated;
grant execute on function public.void_envelope(bigint) to authenticated;
