create or replace function public.emails_guard_sent()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  -- Service role and privileged/direct connections are unrestricted.
  if coalesce(auth.role(), '') <> 'authenticated' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.sent_at is not null then
      raise exception 'sent_at cannot be set by clients' using errcode = '42501';
    end if;
    return new;
  end if;

  if old.sent_at is not null then
    raise exception 'sent emails are immutable' using errcode = '42501';
  end if;

  if new.sent_at is not null then
    raise exception 'sent_at cannot be set by clients' using errcode = '42501';
  end if;

  if new.user_id <> old.user_id then
    raise exception 'user_id cannot be changed' using errcode = '42501';
  end if;

  return new;
end;
$$;

create trigger emails_guard_sent
before insert or update on public.emails
for each row
execute function public.emails_guard_sent();
