create or replace function public.jobs_guard_update()
returns trigger
language plpgsql
as $$
begin
  if new.id is distinct from old.id then
    raise exception 'job id cannot be changed';
  end if;
  if new.garage_id is distinct from old.garage_id then
    raise exception 'job garage cannot be changed';
  end if;
  if new.customer_id is distinct from old.customer_id then
    raise exception 'job customer cannot be changed';
  end if;
  if new.vehicle is distinct from old.vehicle then
    raise exception 'job vehicle cannot be changed';
  end if;

  if new.quote_amount is distinct from old.quote_amount
     and not (old.status = 'quoted' and new.status = 'quoted') then
    raise exception 'quote can only be changed while the job is quoted';
  end if;

  if old.status = 'quoted' then
    if new.status not in ('quoted', 'approved') then
      raise exception 'invalid status transition: % -> %', old.status, new.status;
    end if;
  elsif old.status = 'approved' then
    if new.status not in ('approved', 'in_progress') then
      raise exception 'invalid status transition: % -> %', old.status, new.status;
    end if;
  elsif old.status = 'in_progress' then
    if new.status not in ('in_progress', 'done') then
      raise exception 'invalid status transition: % -> %', old.status, new.status;
    end if;
  else
    raise exception 'job is % and cannot be changed', old.status;
  end if;

  return new;
end;
$$;

