create or replace function public.jobs_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  uid uuid := auth.uid();
  as_customer boolean;
  as_mechanic boolean;
  ok boolean := false;
begin
  -- service_role / no JWT: full access
  if uid is null then
    return new;
  end if;

  if new.id is distinct from old.id
     or new.garage_id is distinct from old.garage_id
     or new.customer_id is distinct from old.customer_id then
    raise exception 'jobs: id, garage_id and customer_id are immutable';
  end if;

  as_customer := (old.customer_id = uid);
  as_mechanic := exists (
    select 1 from public.mechanics m
    where m.garage_id = old.garage_id and m.user_id = uid
  );

  -- R3: customer may only approve a quoted job, changing nothing else
  if as_customer
     and old.status = 'quoted'
     and new.status = 'approved'
     and new.vehicle is not distinct from old.vehicle
     and new.quote_amount is not distinct from old.quote_amount then
    ok := true;
  end if;

  -- R2 / R4: mechanic transitions
  if not ok and as_mechanic then
    if old.status = 'quoted' and new.status = 'quoted' then
      ok := true;
    elsif old.status = 'approved' and new.status = 'in_progress'
          and new.vehicle is not distinct from old.vehicle
          and new.quote_amount is not distinct from old.quote_amount then
      ok := true;
    elsif old.status = 'in_progress' and new.status = 'done'
          and new.vehicle is not distinct from old.vehicle
          and new.quote_amount is not distinct from old.quote_amount then
      ok := true;
    end if;
  end if;

  if not ok then
    raise exception 'jobs: update not permitted';
  end if;

  return new;
end;
$$;

