create or replace function public.jobs_enforce_rules()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_role text := coalesce(auth.role(), current_setting('request.jwt.claim.role', true));
  v_is_mechanic boolean;
begin
  if v_role = 'service_role' then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  if tg_op = 'DELETE' then
    raise exception 'jobs cannot be deleted';
  end if;

  if tg_op = 'INSERT' then
    if v_uid is null then
      raise exception 'not authenticated';
    end if;
    if new.status <> 'quoted' then
      raise exception 'new jobs must be quoted';
    end if;
    if not public.is_mechanic_of(new.garage_id) then
      raise exception 'only mechanics of the garage can open jobs';
    end if;
    return new;
  end if;

  if new.id is distinct from old.id
     or new.garage_id is distinct from old.garage_id
     or new.customer_id is distinct from old.customer_id
     or new.vehicle is distinct from old.vehicle then
    raise exception 'job identity fields cannot be changed';
  end if;

  v_is_mechanic := public.is_mechanic_of(old.garage_id);

  if old.status = 'quoted' then
    if new.status = 'quoted' then
      if not v_is_mechanic then
        raise exception 'only mechanics of the garage can change a quote';
      end if;
      return new;
    elsif new.status = 'approved' then
      if v_uid is distinct from old.customer_id then
        raise exception 'only the customer can approve a quote';
      end if;
