create or replace function public.jobs_before_update()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.id is distinct from old.id
     or new.garage_id is distinct from old.garage_id
     or new.customer_id is distinct from old.customer_id then
    raise exception 'immutable job columns cannot be changed';
  end if;

  if new.vehicle is distinct from old.vehicle then
    raise exception 'vehicle cannot be changed';
  end if;

  if new.status = old.status then
    if old.status = 'quoted' and public.is_mechanic(old.garage_id) then
      return new;
    end if;
    raise exception 'job update not allowed';
  end if;

  if old.status = 'quoted' and new.status = 'approved' then
    if auth.uid() is distinct from old.customer_id then
      raise exception 'only the customer can approve a quote';
    end if;
    if new.quote_amount is distinct from old.quote_amount then
      raise exception 'quote amount cannot change on approval';
    end if;
    return new;
  end if;

  if old.status = 'approved' and new.status = 'in_progress' then
    if not public.is_mechanic(old.garage_id) then
      raise exception 'only a garage mechanic can start a job';
    end if;
    if new.quote_amount is distinct from old.quote_amount then
      raise exception 'quote amount cannot change';
    end if;
    return new;
  end if;

  if old.status = 'in_progress' and new.status = 'done' then
    if not public.is_mechanic(old.garage_id) then
      raise exception 'only a garage mechanic can finish a job';
    end if;
    if new.quote_amount is distinct from old.quote_amount then
      raise exception 'quote amount cannot change';
    end if;
    return new;
  end if;

  raise exception 'invalid job status transition';
end;
$$;

