as $$
begin
  if auth.role() = 'service_role' or current_user in ('postgres', 'supabase_admin') then
    return new;
  end if;

  if new.id is distinct from old.id then
    raise exception 'article id cannot be changed';
  end if;

  if new.author_id is distinct from old.author_id then
    raise exception 'article author cannot be changed';
  end if;

  if old.status = 'published' then
    raise exception 'published articles cannot be changed';
  end if;

  if public.is_editor(auth.uid()) then
    if old.status <> 'in_review' then
      raise exception 'editors can only modify articles in review';
    end if;
    if new.status not in ('in_review', 'published', 'draft') then
      raise exception 'invalid editor status transition';
    end if;
  else
    if old.author_id <> auth.uid() then
      raise exception 'not the article author';
    end if;
    if old.status <> 'draft' then
      raise exception 'writers can only modify their own drafts';
    end if;
    if new.status not in ('draft', 'in_review') then
      raise exception 'writers cannot publish or change submitted articles';
    end if;
  end if;

  return new;
end;
$$;

