-- R1 / R5: only signed-in users, and only their own rows.
create policy referral_codes_select_own
  on public.referral_codes
  for select
  to authenticated
  using (user_id = (select auth.uid()));

create policy referrals_select_own
  on public.referrals
  for select
  to authenticated
  using (
    referrer_id = (select auth.uid())
    or referee_id = (select auth.uid())
  );

create policy credits_select_own
  on public.credits
  for select
  to authenticated
  using (user_id = (select auth.uid()));

-- R2 / R5: no direct writes from the app for any role; no policies exist for
-- insert/update/delete, and the underlying privileges are removed as well.
revoke all on public.referral_codes from anon;
revoke all on public.referrals from anon;
revoke all on public.credits from anon;

revoke insert, update, delete, truncate, references, trigger
  on public.referral_codes from authenticated;
revoke insert, update, delete, truncate, references, trigger
  on public.referrals from authenticated;
revoke insert, update, delete, truncate, references, trigger
  on public.credits from authenticated;

grant select on public.referral_codes to authenticated;
grant select on public.referrals to authenticated;
grant select on public.credits to authenticated;

-- R3 / R4: atomic redemption performed with definer privileges.
create or replace function public.redeem_referral(p_code text)
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_caller         uuid := auth.uid();
  v_owner          uuid;
  v_referral_id    bigint;
  v_referral_count integer;
begin
  if v_caller is null then
    raise exception 'redeem_referral: not authenticated'
      using errcode = '28000';
  end if;

  if p_code is null or length(p_code) = 0 then
    raise exception 'redeem_referral: invalid referral code'
      using errcode = '22023';
  end if;

  -- Serialize concurrent redemptions by the same caller.
  perform pg_advisory_xact_lock(hashtextextended(v_caller::text, 0));

  select rc.user_id
    into v_owner
    from public.referral_codes rc
   where rc.code = p_code
     for update;

  if v_owner is null then
    raise exception 'redeem_referral: invalid referral code'
      using errcode = '22023';
  end if;

  if v_owner = v_caller then
    raise exception 'redeem_referral: cannot redeem your own referral code'
      using errcode = '22023';
  end if;

  if exists (
    select 1 from public.referrals r where r.referee_id = v_caller
  ) then
    raise exception 'redeem_referral: referral code already redeemed'
      using errcode = '23505';
  end if;

  select count(*)
    into v_referral_count
    from public.referrals r
   where r.referrer_id = v_owner;

  if v_referral_count >= 5 then
    raise exception 'redeem_referral: referrer has reached the referral limit'
      using errcode = '22023';
  end if;

  insert into public.referrals (referrer_id, referee_id)
  values (v_owner, v_caller)
  returning id into v_referral_id;

  insert into public.credits (user_id, amount, reason)
  values
    (v_caller, 100, 'referral bonus'),
    (v_owner,  100, 'referral bonus');

  return v_referral_id;
end;
$$;

revoke all on function public.redeem_referral(text) from public;
revoke all on function public.redeem_referral(text) from anon;
grant execute on function public.redeem_referral(text) to authenticated;
```

