-- Enforce column-level update rules (claim / unclaim / mark bought only)
create or replace function public.shopping_items_enforce_update()
returns trigger
language plpgsql
security invoker
set search_path = public
as $$
begin
  if auth.role() = 'service_role' or current_user = 'postgres' then
    return new;
  end if;

  if new.id <> old.id
     or new.household_id <> old.household_id
     or new.name <> old.name
     or new.added_by <> old.added_by then
    raise exception 'shopping_items: immutable columns cannot be changed';
  end if;

  if new.is_bought is distinct from old.is_bought then
    if not (old.is_bought = false and new.is_bought = true) then
      raise exception 'shopping_items: is_bought can only be set to true';
    end if;
    if old.claimed_by is distinct from auth.uid() then
      raise exception 'shopping_items: only the claimer can mark an item bought';
    end if;
    if new.claimed_by is distinct from old.claimed_by then
      raise exception 'shopping_items: cannot change claim while marking bought';
    end if;
  end if;

  if new.claimed_by is distinct from old.claimed_by then
    if old.claimed_by is null and new.claimed_by = auth.uid() then
      if old.is_bought then
        raise exception 'shopping_items: cannot claim a bought item';
      end if;
    elsif old.claimed_by = auth.uid() and new.claimed_by is null then
      if old.is_bought then
        raise exception 'shopping_items: cannot unclaim a bought item';
      end if;
    else
      raise exception 'shopping_items: invalid claim transition';
    end if;
  end if;

  return new;
end;
$$;

create trigger shopping_items_enforce_update
  before update on public.shopping_items
  for each row
  execute function public.shopping_items_enforce_update();

