create or replace function public.redeem_referral(p_code text)
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_caller      uuid := auth.uid();
  v_referrer    uuid;
  v_referral_id bigint;
  v_count       integer;
begin
  if v_caller is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;

  if p_code is null or length(p_code) = 0 then
    raise exception 'invalid referral code' using errcode = '22023';
  end if;

  -- serialize concurrent redemptions by the same caller
  perform pg_advisory_xact_lock(hashtext(v_caller::text));

  -- serialize concurrent redemptions of the same code (locks the code row)
  select rc.user_id
    into v_referrer
    from public.referral_codes rc
   where rc.code = p_code
     for update;

  if not found then
    raise exception 'referral code does not exist' using errcode = 'P0002';
  end if;

  if v_referrer = v_caller then
    raise exception 'cannot redeem your own referral code' using errcode = 'P0001';
  end if;

  if exists (
    select 1 from public.referrals r where r.referee_id = v_caller
  ) then
    raise exception 'caller has already redeemed a referral code' using errcode = 'P0001';
  end if;

  select count(*)
    into v_count
    from public.referrals r
   where r.referrer_id = v_referrer;

  if v_count >= 5 then
    raise exception 'referral code owner has reached the referral limit' using errcode = 'P0001';
  end if;

  insert into public.referrals (referrer_id, referee_id)
  values (v_referrer, v_caller)
  returning id into v_referral_id;

  insert into public.credits (user_id, amount, reason)
  values
    (v_caller,   100, 'referral signup bonus'),
    (v_referrer, 100, 'referral reward');

  return v_referral_id;
end;
$$;

