create policy records_select
  on public.records
  for select
  to authenticated
  using (
    public.is_org_member(org_id)
    and (deleted_at is null or public.is_org_admin(org_id))
  );

-- R2: members (and admins) can create records in their orgs, never pre-deleted
create policy records_insert
  on public.records
  for insert
  to authenticated
  with check (
    public.is_org_member(org_id)
    and deleted_at is null
  );

-- R2: members edit non-deleted records; admins may also set deleted_at.
-- Members can never produce a row with deleted_at set (WITH CHECK).
create policy records_update
  on public.records
  for update
  to authenticated
  using (
    (deleted_at is null and public.is_org_member(org_id))
    or public.is_org_admin(org_id)
  )
  with check (
    (deleted_at is null and public.is_org_member(org_id))
    or public.is_org_admin(org_id)
  );

