-- R3: audit trail on every record insert/update
-- ---------------------------------------------------------------------------
create or replace function public.records_audit_trigger()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.audit_log (record_id, action, actor)
  values (new.id, lower(tg_op), auth.uid());
  return null;
end;
$$;

create trigger records_audit
  after insert or update on public.records
  for each row
  execute function public.records_audit_trigger();

-- ---------------------------------------------------------------------------
-- R2 / R5: only admins may set deleted_at, and only restore_record() may
-- clear it (so the 30-day rule cannot be bypassed with a plain UPDATE).
-- Trusted server-side code (service role, no JWT) is left unrestricted (R6).
-- ---------------------------------------------------------------------------
create or replace function public.records_guard_deleted_at()
returns trigger
language plpgsql
security invoker
set search_path = public
as $$
begin
  if new.deleted_at is distinct from old.deleted_at then
    if auth.uid() is null then
      return new;
    end if;

    if coalesce(current_setting('app.restore_record', true), 'off') = 'on' then
      return new;
    end if;

    if old.deleted_at is not null then
      raise exception 'record % is deleted; use restore_record()', old.id
        using errcode = '42501';
    end if;

    if not public.is_org_admin(old.org_id) then
      raise exception 'only organization admins can delete records'
        using errcode = '42501';
    end if;
  end if;

  return new;
end;
$$;

create trigger records_guard_deleted_at
  before update on public.records
  for each row
  execute function public.records_guard_deleted_at();

-- ---------------------------------------------------------------------------
-- R5: restore_record
-- ---------------------------------------------------------------------------
create or replace function public.restore_record(p_record_id bigint)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_org_id     bigint;
  v_deleted_at timestamptz;
begin
  if auth.uid() is null then
    raise exception 'restore_record: not authenticated' using errcode = '42501';
  end if;

  select r.org_id, r.deleted_at
    into v_org_id, v_deleted_at
    from public.records r
   where r.id = p_record_id;

  if not found then
    raise exception 'restore_record: record % does not exist', p_record_id
      using errcode = 'P0002';
  end if;

  if not public.is_org_admin(v_org_id) then
    raise exception 'restore_record: only organization admins can restore records'
      using errcode = '42501';
  end if;

  if v_deleted_at is null then
    raise exception 'restore_record: record % is not deleted', p_record_id
      using errcode = '22023';
  end if;

  if v_deleted_at < now() - interval '30 days' then
    raise exception 'restore_record: record % was deleted more than 30 days ago', p_record_id
      using errcode = '22023';
  end if;

  perform set_config('app.restore_record', 'on', true);

  update public.records
     set deleted_at = null
   where id = p_record_id;

  perform set_config('app.restore_record', 'off', true);
end;
$$;

revoke all on function public.restore_record(bigint) from public;
grant execute on function public.restore_record(bigint) to authenticated, service_role;

