-- Helper functions (security definer to avoid RLS recursion on org_members)
create or replace function public.is_org_member(p_org_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.org_members
    where org_id = p_org_id and user_id = auth.uid()
  );
$$;

create or replace function public.is_org_admin(p_org_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.org_members
    where org_id = p_org_id and user_id = auth.uid() and role = 'admin'
  );
$$;

create or replace function public.is_record_org_admin(p_record_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.records r
    join public.org_members m on m.org_id = r.org_id
    where r.id = p_record_id
      and m.user_id = auth.uid()
      and m.role = 'admin'
  );
$$;

-- Enable RLS
alter table public.org_members enable row level security;
alter table public.records enable row level security;
alter table public.audit_log enable row level security;

-- org_members: members see only their own memberships
create policy org_members_select_own
  on public.org_members
  for select
  to authenticated
  using (user_id = auth.uid());

-- records: members see non-deleted org records; admins also see deleted
create policy records_select
  on public.records
  for select
  to authenticated
  using (
    public.is_org_member(org_id)
    and (deleted_at is null or public.is_org_admin(org_id))
  );

-- records: members can insert into their org (never pre-deleted)
create policy records_insert
  on public.records
  for insert
  to authenticated
  with check (
    public.is_org_member(org_id)
    and deleted_at is null
  );

-- records: members can edit non-deleted records; only admins may set deleted_at
create policy records_update
  on public.records
  for update
  to authenticated
  using (
    public.is_org_member(org_id)
    and deleted_at is null
  )
  with check (
    public.is_org_member(org_id)
    and (deleted_at is null or public.is_org_admin(org_id))
  );

-- audit_log: only admins of the record's org can read
