  on public.audit_log
  for select
  to authenticated
  using (public.is_record_org_admin(record_id));

-- Guard trigger: org_id immutable; only admins may change deleted_at
create or replace function public.records_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.role() is distinct from 'authenticated' then
    return new;
  end if;

  if new.org_id is distinct from old.org_id then
    raise exception 'org_id is immutable';
  end if;

  if new.deleted_at is distinct from old.deleted_at then
    if not public.is_org_admin(old.org_id) then
      raise exception 'only admins can delete or restore records';
    end if;
  end if;

  return new;
end;
$$;

create trigger records_guard
before update on public.records
for each row execute function public.records_guard();

-- Audit trigger: every insert/update writes an audit row
create or replace function public.records_audit()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if tg_op = 'INSERT' then
    insert into public.audit_log (record_id, action, actor)
    values (new.id, 'insert', auth.uid());
  elsif tg_op = 'UPDATE' then
    insert into public.audit_log (record_id, action, actor)
    values (new.id, 'update', auth.uid());
  end if;
  return new;
end;
$$;

create trigger records_audit
after insert or update on public.records
for each row execute function public.records_audit();

-- restore_record: admin-only, deleted-only, within 30 days
create or replace function public.restore_record(p_record_id bigint)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_org_id bigint;
  v_deleted_at timestamptz;
begin
  if auth.role() = 'service_role' then
    update public.records set deleted_at = null where id = p_record_id;
    return;
  end if;

  select org_id, deleted_at
    into v_org_id, v_deleted_at
  from public.records
  where id = p_record_id;

  if not found then
    raise exception 'record % not found', p_record_id;
  end if;

  if not public.is_org_admin(v_org_id) then
    raise exception 'not authorized to restore record %', p_record_id;
  end if;

  if v_deleted_at is null then
    raise exception 'record % is not deleted', p_record_id;
  end if;

  if v_deleted_at < now() - interval '30 days' then
    raise exception 'record % was deleted more than 30 days ago', p_record_id;
  end if;

  update public.records
  set deleted_at = null
  where id = p_record_id;
end;
$$;

