revoke all on public.records from anon, authenticated;
revoke all on public.audit_log from anon, authenticated;

grant select on public.org_members to authenticated;
grant select, insert, update on public.records to authenticated;
grant select on public.audit_log to authenticated;

grant all on public.org_members to service_role;
grant all on public.records to service_role;
grant all on public.audit_log to service_role;

revoke execute on function public.is_org_member(bigint) from public, anon;
revoke execute on function public.is_org_admin(bigint) from public, anon;
revoke execute on function public.is_record_org_admin(bigint) from public, anon;
revoke execute on function public.records_guard() from public, anon, authenticated;
revoke execute on function public.records_audit() from public, anon, authenticated;
revoke execute on function public.restore_record(bigint) from public, anon;

