-- Helper: is the given user a reviewer? SECURITY DEFINER so it bypasses RLS on public.reviewers.
create or replace function public.is_reviewer(uid uuid default auth.uid())
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.reviewers r where r.user_id = uid);
$$;

revoke all on function public.is_reviewer(uuid) from public, anon;
grant execute on function public.is_reviewer(uuid) to authenticated, service_role;

-- Enable RLS
alter table public.reviewers enable row level security;
alter table public.proposals enable row level security;
alter table public.reviews   enable row level security;

-- ---------------------------------------------------------------- reviewers
-- R5: users may only see their own reviewer row; nobody can write through the app.
create policy reviewers_select_self on public.reviewers
for select to authenticated
using (user_id = auth.uid());

-- ---------------------------------------------------------------- proposals
-- R1: speakers see their own proposals; reviewers see every proposal.
create policy proposals_select on public.proposals
for select to authenticated
using (
  speaker_id = auth.uid()
  or public.is_reviewer(auth.uid())
);

-- R2: signed-in users may submit proposals as themselves, always 'submitted'.
create policy proposals_insert on public.proposals
for insert to authenticated
with check (
  speaker_id = auth.uid()
  and status = 'submitted'
);

-- R2: speakers may edit their own proposals only while undecided (and cannot
-- change ownership or status).
create policy proposals_update on public.proposals
for update to authenticated
using (
  speaker_id = auth.uid()
  and status = 'submitted'
)
with check (
  speaker_id = auth.uid()
  and status = 'submitted'
);

-- ---------------------------------------------------------------- reviews
-- R4: reviewers see only their own reviews; speakers see reviews of their own
-- proposals only after a decision has been made.
create policy reviews_select on public.reviews
for select to authenticated
using (
  reviewer_id = auth.uid()
  or exists (
    select 1
    from public.proposals p
    where p.id = reviews.proposal_id
      and p.speaker_id = auth.uid()
      and p.status <> 'submitted'
  )
);

-- R3: reviewers may review an undecided proposal once, as themselves, and never
-- their own proposal.
create policy reviews_insert on public.reviews
for insert to authenticated
with check (
  reviewer_id = auth.uid()
  and public.is_reviewer(auth.uid())
  and exists (
    select 1
    from public.proposals p
    where p.id = reviews.proposal_id
      and p.status = 'submitted'
      and p.speaker_id <> auth.uid()
  )
);

-- R3: reviewers may edit their own reviews while the proposal is undecided.
create policy reviews_update on public.reviews
for update to authenticated
using (
  reviewer_id = auth.uid()
  and public.is_reviewer(auth.uid())
  and exists (
    select 1
    from public.proposals p
    where p.id = reviews.proposal_id
      and p.status = 'submitted'
      and p.speaker_id <> auth.uid()
  )
)
with check (
  reviewer_id = auth.uid()
  and public.is_reviewer(auth.uid())
  and exists (
    select 1
    from public.proposals p
    where p.id = reviews.proposal_id
      and p.status = 'submitted'
      and p.speaker_id <> auth.uid()
  )
);

-- ---------------------------------------------------------------- grants
revoke all on public.reviewers from anon, authenticated;
revoke all on public.proposals from anon, authenticated;
revoke all on public.reviews   from anon, authenticated;

grant select on public.reviewers to authenticated;

grant select, insert, update on public.proposals to authenticated;
grant usage, select on sequence public.proposals_id_seq to authenticated;

grant select, insert, update on public.reviews to authenticated;

-- R6: server-side code with the service role keeps full access.
grant all on public.reviewers to service_role;
grant all on public.proposals to service_role;
grant all on public.reviews   to service_role;
grant usage, select on sequence public.proposals_id_seq to service_role;
