create policy hoa_admins_select_own
on public.hoa_admins
for select
to authenticated
using (user_id = auth.uid());

-- R1: residents see permits of their unit, HOA admins see every permit
create policy permits_select
on public.permits
for select
to authenticated
using (
  public.is_hoa_admin(auth.uid())
  or public.is_resident_of(auth.uid(), unit_id)
);

-- R2: residents add permits for their own unit, max 2 active, not revoked, <= 365 days out
create policy permits_insert_resident
on public.permits
for insert
to authenticated
with check (
  revoked = false
  and valid_until <= current_date + 365
  and public.is_resident_of(auth.uid(), unit_id)
