with check (public.is_resident_of(auth.uid(), unit_id));

-- R4: HOA admins may update (revoke) any permit
create policy permits_update_admin
on public.permits
for update
to authenticated
using (public.is_hoa_admin(auth.uid()))
with check (public.is_hoa_admin(auth.uid()));

-- R3/R4: immutability of id/unit_id/valid_until and one-way revoked transition
create or replace function public.permits_guard_update()
returns trigger
language plpgsql
set search_path = public, auth
as $$
begin
  -- service_role / postgres / admin roles keep full access
  if current_user not in ('anon', 'authenticated') then
    return new;
  end if;

  if new.id is distinct from old.id
     or new.unit_id is distinct from old.unit_id
     or new.valid_until is distinct from old.valid_until then
    raise exception 'Only the plate of a permit may be changed';
  end if;

  if new.revoked is distinct from old.revoked then
    if not (new.revoked and not old.revoked) then
      raise exception 'Permits cannot be un-revoked';
    end if;
    if not public.is_hoa_admin(auth.uid()) then
      raise exception 'Only HOA admins can revoke permits';
    end if;
  end if;

  return new;
end;
$$;

revoke all on function public.permits_guard_update() from public;

create trigger permits_guard_update
before update on public.permits
for each row execute function public.permits_guard_update();
