  select exists (
    select 1 from public.break_glass_grants g
    where g.patient_id = p_patient_id
      and g.clinician_id = p_clinician_id
      and g.expires_at > now()
  );
$$;

create or replace function public.break_glass(p_patient_id bigint, p_reason text)
returns timestamptz
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_reason text := btrim(coalesce(p_reason, ''));
  v_expires_at timestamptz := now() + interval '1 hour';
begin
  if v_uid is null then
    raise exception 'break_glass: caller is not authenticated' using errcode = '42501';
  end if;

  if not exists (select 1 from public.clinicians c where c.user_id = v_uid) then
    raise exception 'break_glass: caller is not a clinician' using errcode = '42501';
  end if;

  if p_patient_id is null or not exists (select 1 from public.patients p where p.id = p_patient_id) then
    raise exception 'break_glass: patient does not exist' using errcode = 'P0002';
  end if;

  if length(v_reason) < 10 then
    raise exception 'break_glass: reason must be at least 10 characters' using errcode = '22023';
  end if;

  insert into public.break_glass_grants (patient_id, clinician_id, reason, expires_at)
  values (p_patient_id, v_uid, v_reason, v_expires_at);

  return v_expires_at;
end;
$$;

