  );
$$;

create or replace function public.has_break_glass_access(p_patient_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.break_glass_grants g
    where g.patient_id = p_patient_id
      and g.clinician_id = (select auth.uid())
      and g.expires_at > now()
  );
$$;

create or replace function public.can_read_patient(p_patient_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select public.is_clinician()
     and (
       public.has_care_team_access(p_patient_id)
       or public.has_break_glass_access(p_patient_id)
     );
$$;

create or replace function public.break_glass(p_patient_id bigint, p_reason text)
returns timestamptz
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_expires_at timestamptz;
begin
  if not public.is_clinician() then
    raise exception 'break_glass: caller is not a clinician'
      using errcode = '42501';
  end if;

  if p_patient_id is null
     or not exists (select 1 from public.patients p where p.id = p_patient_id) then
    raise exception 'break_glass: patient % does not exist', p_patient_id
      using errcode = '23503';
  end if;

  if length(btrim(coalesce(p_reason, ''))) < 10 then
    raise exception 'break_glass: reason must be at least 10 characters'
      using errcode = '22023';
  end if;

  v_expires_at := now() + interval '1 hour';

  insert into public.break_glass_grants (patient_id, clinician_id, reason, expires_at)
  values (p_patient_id, (select auth.uid()), btrim(p_reason), v_expires_at);

  return v_expires_at;
end;
$$;

create policy clinicians_select_self
